INSERT INTO `pages` (`id`, `name`, `content`, `user_id`, `image`, `template`, `description`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Home', '<shortcode>[hero-banner style=\"2\" title=\"Senior &lt;span&gt;{Full Stack}&lt;/span&gt;Web &amp; App developer\" subtitle=\"Hey, I’m Asad\" description=\"With expertise in modern technologies like &lt;span&gt;Flutter&lt;/span&gt;, &lt;span&gt;Dart&lt;/span&gt;, &lt;span&gt;Firebase&lt;/span&gt;, &lt;span&gt;Node.js&lt;/span&gt;, &lt;span&gt;React.js&lt;/span&gt;, and &lt;span&gt;Laravel&lt;/span&gt;, I build cross-platform apps and full-stack web solutions that are fast, scalable, and user-focused.\" primary_button_text=\"Download My CV\" primary_button_link=\"/storage/main/resume/asadresume.pdf\" primary_button_icon=\"ti ti-download\" open_primary_link_in_the_new_tab=\"yes\" open_secondary_link_in_the_new_tab=\"no\" below_button_text=\"...and more\" quantity=\"9\" name_1=\"Express Js\" image_1=\"icons/icons8-express-js-100.png\" name_2=\"Firebase\" image_2=\"icons8-firebase-100.png\" name_3=\"MongoDB\" image_3=\"icons/icons8-mongo-db-100.png\" name_4=\"Node.js\" image_4=\"icons/icons8-node-js-100.png\" name_5=\" CSS\" image_5=\"icons/icons8-css-100.png\" name_6=\"Dart\" image_6=\"icons/icons8-dart-language-100.png\" name_7=\"Flutter\" image_7=\"icons/icons8-flutter-100.png\" name_8=\"React\" image_8=\"icons/icons8-react-100.png\" name_9=\"Laravel\" image_9=\"icons/icons8-laravel-100.png\" background_image=\"code/general/hero-bg.png\" background_image_dark=\"code/general/hero-bg-dark.png\" right_image=\"media/achi.png\" right_image_shape=\"code/general/people-shape.png\" filter_gray_image_in_dark_mode=\"yes\" enable_lazy_loading=\"no\"][/hero-banner]</shortcode><shortcode>[stats-counter style=\"2\" quantity=\"4\" label_1=\"Years Experience\" count_1=\"2\" icon_1=\"ti ti-crown\" label_2=\"Projects Completed\" count_2=\"10\" icon_2=\"ti ti-device-desktop\" label_3=\"Satisfied Clients\" count_3=\"5+\" icon_3=\"ti ti-heart-spark\" label_4=\"Awards Winner\" count_4=\"1\" icon_4=\"ti ti-award\" background_image=\"code/general/static-bg.png\" enable_lazy_loading=\"no\"][/stats-counter]</shortcode><shortcode>[corporation title=\"More than +2 &lt;span&gt;companies &lt;br /&gt;&lt;/span&gt; trusted &lt;span&gt;worldwide_&lt;/span&gt;\" subtitle=\"Cooperation\" companies_quantity=\"2\" companies_name_1=\"Synet Digital\" companies_image_1=\"without-details-e1715781536475.png\" companies_name_2=\"Cyphersol\" companies_image_2=\"logo.png\" contact_avatar=\"code/general/favicon.png\" contacts_quantity=\"1\" contacts_label_1=\"Contact\" contacts_icon_1=\"ti ti-phone-calling\" journeys_quantity=\"6\" journeys_date_1=\"15 Jul\" journeys_title_1=\"Jordanian Sports App\" journeys_date_2=\"30 Jun\" journeys_title_2=\"Cypher App\" journeys_date_3=\"26 May\" journeys_title_3=\"Qik-E\" journeys_date_4=\"17 Apr\" journeys_title_4=\"Session Buddy App\" journeys_date_5=\"05 Mar\" journeys_title_5=\"Green Guide App\" journeys_date_6=\"02 Feb\" journeys_title_6=\"Splitify Ui\" enable_lazy_loading=\"yes\"][/corporation]</shortcode><p>&nbsp;</p><shortcode>[services style=\"2\" title=\"solutions &lt;span class=\'text-300\'&gt;customized&lt;br&gt;to meet your requirements&lt;/span&gt;\" subtitle=\"Cooperation\" service_ids=\"7,8,10,11,12,13,14\" bottom_text=\"Excited to take on &lt;span class=\'text-dark\'&gt;new projects&lt;/span&gt; and collaborate. &lt;br&gt;Let\'s chat about your ideas. &lt;a href=\'\' class=\'text-primary-2\'&gt;Reach out!&lt;/a&gt;\" show_image_on_hover=\"yes\" enable_lazy_loading=\"yes\"][/services]</shortcode><shortcode>[experience title=\"+2 &lt;span&gt;years of&lt;/span&gt; passion &lt;span&gt;for &lt;br /&gt; programming techniques&lt;/span&gt;\" subtitle=\"Experience\" role_title=\"Flutter Developer\" role_description=\"Led development of cross-platform mobile apps using &lt;span&gt;Flutter&lt;/span&gt;, delivering seamless user experiences and clean UI implementations across Android and iOS. Integrated scalable backend solutions with &lt;span&gt;Firebase&lt;/span&gt;, &lt;span&gt;Node.js&lt;/span&gt;, and &lt;span&gt;Laravel&lt;/span&gt; to support real-time features and secure data flow. Collaborated with designers and product owners to convert &lt;span&gt;Figma&lt;/span&gt; designs into fully functional, responsive UIs using &lt;span&gt;GetX&lt;/span&gt; for state management. Developed and maintained full-stack web applications using &lt;span&gt;React&lt;/span&gt;, &lt;span&gt;MongoDB&lt;/span&gt;, and &lt;span&gt;Express.js&lt;/span&gt;, ensuring high performance and maintainability. Implemented push notifications with &lt;span&gt;Firebase Cloud Messaging&lt;/span&gt; to improve user engagement and deliver real-time updates. Deployed and published multiple apps on &lt;span&gt;Google Play Store&lt;/span&gt; and &lt;span&gt;Apple App Store&lt;/span&gt;, including end-to-end asset handling, builds, and store listing management. Provided long-term app maintenance, performance optimization, and modular upgrades for scalability and clean architecture.\" experiences_quantity=\"2\" experiences_date_1=\"2023-Present\" experiences_title_1=\"Cyphersol\" experiences_logo_1=\"logo.png\" experiences_date_2=\"2022-2023\" experiences_title_2=\"GhairMulki Software House\" experiences_logo_2=\"logo-dark.png\" skills_quantity=\"10\" skills_name_1=\"Flutter\" skills_name_2=\"Dart\" skills_name_3=\"Firebase\" skills_name_4=\"Laravel\" skills_name_5=\"MERN\" skills_name_6=\"MySql\" skills_name_7=\"Html \" skills_name_8=\"CSS\" background_image=\"code/general/services-bg.png\" enable_lazy_loading=\"yes\"][/experience]</shortcode><shortcode>[resume style=\"2\" resume_1_title=\"Education\" resume_1_title_icon=\"ti ti-school\" resume_1_quantity=\"3\" resume_1_time_1=\"2018-2020\" resume_1_title_1=\"Matriculation\" resume_1_subtitle_1=\"Ibn e Qasim High School Basti Malook\" resume_1_time_2=\"2020 - 2022\" resume_1_title_2=\"Intermediate\" resume_1_subtitle_2=\"Kips College\" resume_1_time_3=\"2022- 2026\" resume_1_title_3=\"Bachelor\'s of Computer Science\" resume_1_subtitle_3=\"NUMl\" resume_1_time