INSERT INTO `pf_projects` (`id`, `name`, `description`, `content`, `place`, `client`, `is_featured`, `image`, `images`, `views`, `status`, `created_at`, `updated_at`, `author`, `start_date`, `order`) VALUES
(11, 'GreenGuide – Home Gardening Assistant', 'GreenGuide is a Flutter-based mobile gardening app designed to help beginners and hobbyists grow and manage plants at home. The app provides plant care tips, growth tracking, personalized schedules, and real-time notifications using Firebase and FCM.', '<p><span style=\"font-size:21px;\"><strong>GreenGuide</strong> is a beautifully crafted Flutter app built to support home gardening enthusiasts in selecting, growing, and caring for plants. Designed specifically for beginner gardeners, the app features a user-friendly interface that guides users through personalized care routines, seasonal planting advice, and community engagement.</span></p><p><span style=\"font-size:21px;\">The app includes modules for plant selection based on preferences, customized watering/fertilizing schedules, and a growth tracking log. Admins can manage the plant database, update content, and support users. Real-time updates and care reminders are powered by <strong>Firebase Cloud Messaging (FCM)</strong>, enhancing user engagement and plant health maintenance.</span></p><p><span style=\"font-size:21px;\">The UI/UX was fully developed in Flutter with responsive layouts, modular widget design, and a consistent theme across all screens. Firebase was used for database and authentication, while FCM handles notification delivery.</span></p><hr><h3><span style=\"font-size:21px;\">👩‍🌾 <strong>Users Can:</strong></span></h3><ul><li><span style=\"font-size:21px;\">Create a gardening profile with preferences</span></li><li><span style=\"font-size:21px;\">Get recommended plants and care plans</span></li><li><span style=\"font-size:21px;\">Receive care reminders via FCM (watering, pruning, fertilizing)</span></li><li><span style=\"font-size:21px;\">Log plant health, growth, and care activity</span></li><li><span style=\"font-size:21px;\">Join community discussions for gardening advice</span></li></ul><hr><h3><span style=\"font-size:21px;\">🔧 <strong>Key Features:</strong></span></h3><p><span style=\"font-size:21px;\">🌱 Plant selection and recommendation system</span>&nbsp;<br><span style=\"font-size:21px;\">🪴 Personalized care schedules for watering, fertilizing, etc.</span>&nbsp;<br><span style=\"font-size:21px;\">📆 Reminders and alerts via Firebase Cloud Messaging</span>&nbsp;<br><span style=\"font-size:21px;\">📈 Growth tracking logs for plant monitoring</span>&nbsp;<br><span style=\"font-size:21px;\">👥 Community forum UI for user engagement</span>&nbsp;<br><span style=\"font-size:21px;\">🗂 Admin control panel for managing plant data and content</span>&nbsp;<br><span style=\"font-size:21px;\">🎨 Intuitive, beginner-friendly UI with clean visual hierarchy</span></p><hr><h3><span style=\"font-size:21px;\">🧩 <strong>Tech Stack:</strong></span></h3><ul><li><span style=\"font-size:21px;\"><strong>Frontend:</strong> Flutter (Dart)</span></li><li><span style=\"font-size:21px;\"><strong>State Management:</strong> GetX</span></li><li><span style=\"font-size:21px;\"><strong>Backend/Database:</strong> Firebase (Firestore, Auth)</span></li><li><span style=\"font-size:21px;\"><strong>Notifications:</strong> Firebase Cloud Messaging (FCM)</span></li><li><span style=\"font-size:21px;\"><strong>UI Tooling:</strong> flutter_screenutil for responsiveness</span></li><li><span style=\"font-size:21px;\"><strong>Architecture:</strong> Modular widget/component design</span></li></ul><p>&nbsp;</p><p>&nbsp;</p><p><img class=\"image_resized\" style=\"aspect-ratio:540/1200;width:50%;\" src=\"https://devzephyr.com/storage/green-guide/whatsapp-image-2025-07-23-at-220425.jpeg\" alt=\"WhatsApp Image 2025-07-23 at 22.04.25\" width=\"540\" height=\"1200\" loading=\"lazy\"><img class=\"image_resized\" style=\"aspect-ratio:540/1200;width:50%;\" src=\"https://devzephyr.com/storage/green-guide/whatsapp-image-2025-07-23-at-220425-1.jpeg\" alt=\"WhatsApp Image 2025-07-23 at 22.04.25 (1)\" width=\"540\" height=\"1200\" loading=\"lazy\"><br><br><img class=\"