INSERT INTO `pf_services` (`id`, `category_id`, `name`, `description`, `content`, `is_featured`, `image`, `images`, `views`, `status`, `created_at`, `updated_at`, `order`) VALUES
(7, 6, 'Cross-Platform App Development', 'Build high-performance apps for Android & iOS from a single codebase.', '<p>I develop modern, high-performance mobile apps using <strong>Flutter and Dart</strong>, ensuring consistency, responsiveness, and scalability. Whether you need an MVP or a full production release, I handle everything from architecture to deployment.</p>', 0, NULL, NULL, 0, 'published', '2025-07-24 01:31:22', '2025-07-24 01:51:19', 0),
(8, 7, 'UI UX implementation', 'Transform designs into beautiful, interactive mobile interfaces.', '<p><span style=\"font-size:21px;\">I specialize in crafting pixel-perfect UI in Flutter based on custom designs or Figma files. My workflow ensures responsive layouts, smooth animations, and consistent theming — making your app visually appealing and intuitive to use across all devices.</span></p>', 0, NULL, NULL, 0, 'published', '2025-07-24 01:32:39', '2025-07-24 01:53:54', 0),
(10, 5, 'Serverless Backend', 'Real-time, secure, and cost-effective backend solutions.', '<p><span style=\"font-size:21px;\">I integrate core Firebase services like <strong>Authentication</strong>, <strong>Firestore</strong>, <strong>Cloud Functions</strong>, <strong>Storage</strong>, and <strong>Firebase Cloud Messaging (FCM)</strong> — enabling live data updates, secure user auth, and scalable serverless logic without managing your own servers.</span></p>', 0, NULL, NULL, 0, 'published', '2025-07-24 01:33:46', '2025-07-24 01:53:01', 0),
(11, 10, 'Push Notifications & Real-Time Features', 'Keep users engaged with real-time alerts and updates.', '<p><span style=\"font-size:21px;\">I set up push notifications using <strong>FCM</strong> and implement real-time data syncing via Firestore or listeners. Whether it\'s chat apps, booking confirmations, or delivery updates — I make your app feel live and interactive.</span></p>', 0, NULL, NULL, 0, 'published', '2025-07-24 01:34:21', '2025-07-24 01:34:23', 0),
(12, 13, 'Admin Panel & Dashboard Development', 'Easily manage your platform from a secure backend interface.', '<p><span style=\"font-size:21px;\">I build <strong>admin dashboards</strong> using Flutter Web or React.js to allow full control over app data, users, orders, and content. Role-based access and analytics features can also be added for better operational visibility.</span></p>', 0, NULL, NULL, 0, 'published', '2025-07-24 01:34:54', '2025-07-24 01:34:56', 0),
(13, 14, 'Full Stack Web Development', 'Create powerful web applications with complete frontend and backend control.', '<p><span style=\"font-size:21px;\"><strong>Create powerful web applications with complete frontend and backend control.</strong></span> &nbsp;<br><span style=\"font-size:21px;\">I develop full-stack solutions using <strong>React.js</strong>, <strong>Node.js</strong>, <strong>MongoDB</strong>, and <strong>Laravel</strong>. From user authentication and custom dashboards to RESTful APIs and payment systems, I deliver end-to-end web platforms optimized for speed, security, and scalability.</span></p>', 0, NULL, NULL, 0, 'published', '2025-07-24 01:35:56', '2025-07-24 01:52:19', 0),
(14, 5, 'Custom API Development', 'Connect your app to smart, scalable backend systems.', '<p><span style=\"font-size:21px;\">I develop custom APIs with <strong>Node.js/Express</strong> or <strong>Laravel</strong> and integrate them with mobile or web frontends. This includes CRUD operations, authentication (JWT), and third-party services — all with secure, RESTful architecture.</span></p>', 0, NULL, NULL, 0, 'published', '2025-07-24 01:36:45', '2025-07-24 01:51:54', 0),
(15, 8, 'App Publishing & Store Deployment', 'Take your app live on Play Store and App Store, stress-free.', '<p><span style=\"font-size:21px;\">From generating signed builds to crafting store listings and uploading to both stores, I handle every aspect of app deployment — including fixing rejection issues, preparing assets, managing updates, and setting versioning strategies.</span></p>', 0, NULL, NULL, 0, 'published', '2025-07-24 01:37:14', '2025-07-24 01:37:14', 0),
(16, 11, 'App Maintenance & Upgrades', 'Post-launch support to keep your app fast, secure, and up-to-date.', '<p data-start=\"3591\" data-end=\"3874\"><span style=\"font-size:21px;\">I offer maintenance services including bug fixing, performance optimization, Flutter version upgrades, and feature enhancements. Your app stays healthy and competitive with regular updates and code refactoring.</span></p>', 0, NULL, NULL, 0, 'published', '2025-07-24 01:37:47', '2025-07-24 01:37:47', 0);
INSERT INTO `pf_service_categories` (`id`, `parent_id`, `name`, `description`, `image`, `order`, `status`, `created_at`, `updated_at`) VALUES
(5, NULL, 'Backend Development', 'Seamless backend development using Node.js, MongoDB, MySQL,Php and REST APIs.', NULL, 0, 'published', '2025-07-24 00:30:28', '2025-07-24 00:30:41'),
(6, NULL, 'Mobile App Development', 'Cross-platform mobile apps built with Flutter for Android & iOS with high performance and native feel.', NULL, 0, 'published', '2025-07-24 00:30:59', '2025-07-24 00:30:59'),
(7, NULL, 'Flutter UI/UX Design', 'Pixel-perfect, responsive UI development using Flutter. Follows Material Design and custom animations.', NULL, 0, 'published', '2025-07-24 00:31:15', '2025-07-24 00:31:15'),
(8, NULL, 'App Publishing & Deployment', 'Full support for Google Play Store & Apple App Store publishing, including bundle signing, icons, and screenshots.', NULL, 0, 'published', '2025-07-24 00:31:32', '2025-07-24 00:31:32'),
(9, NULL, 'Backend Integration', 'Seamless backend connectivity using Firebase, Node.js, MongoDB, MySQL, and REST APIs.', NULL, 0, 'published', '2025-07-24 00:31:51', '2025-07-24 00:31:51'),
(10, NULL, 'Push Notifications & Realtime Features', 'Implementing Firebase Cloud Messaging, realtime updates, in-app alerts, and chat systems.', NULL, 0, 'published', '2025-07-24 00:32:11', '2025-07-24 00:32:11'),
(11, NULL, 'Maintenance & App Optimization', 'Debugging, performance tuning, and refactoring to ensure smooth performance and scalability.', NULL, 0, 'published', '2025-07-24 00:32:40', '2025-07-24 00:32:40'),
(12, NULL, 'Web Integration', 'Integration with web portals using APIs or building simple responsive frontends with React.js or HTML/CSS/JS.', NULL, 0, 'published', '2025-07-24 00:33:06', '2025-07-24 00:33:06'),
(13, NULL, 'Custom Dashboard or Admin Panels', 'Admin interfaces for app content or user management using Flutter Web or lightweight web stacks.', NULL, 0, 'published', '2025-07-24 00:33:22', '2025-07-24 00:33:22'),
(14, NULL, 'Full Stack Web Development (MERN / Laravel)', 'Create powerful web applications with complete frontend and backend control.', NULL, 0, 'published', '2025-07-24 01:35:25', '2025-07-24 01:35:25');
